import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.ts";
import { schema } from "../app/documents/[id]/page.schema.ts";

test("document is refused to someone signed in without documents.edit", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: [] }), "refused");
});

test("document sends someone signed out to sign in", () => {
  assert.equal(decide(schema.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("document opens to someone who holds documents.edit", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: ["documents.edit"] }), "allowed");
});
